r"""Get this PC ready for Boardwright, every time the server starts.

When Claude Code installs the Boardwright plugin there is no setup step,
so the server does the setup itself as it starts:

- creates the data folders under ``%USERPROFILE%\Boardwright``
- copies the verified parts and fab profiles from an older eda-agent
  install, once
- deploys the Altium bridge scripts when this build has not deployed
  them yet (a marker file records which build did)
- writes ``Start Boardwright in Altium.cmd``, which starts the bridge in
  the running Altium; the installer's desktop shortcut runs it, and it is
  rewritten whenever the runtime moves (a plugin update)

All of it is quiet and fast when nothing changed. Nothing may print to
stdout, which carries the MCP protocol: messages go to stderr.
"""
from __future__ import annotations

import contextlib
import io
import shutil
import sys
from pathlib import Path
from typing import Callable, Optional

from . import __version__, engine, paths

MARKER = ".boardwright-build"


def _log(msg: str) -> None:
    print(f"boardwright: {msg}", file=sys.stderr, flush=True)


def build_id() -> str:
    """Identifies the scripts this build ships (Boardwright + engine version)."""
    return f"boardwright {__version__} / {engine.ENGINE_PACKAGE} {engine.version()}"


def deployed_build() -> Optional[str]:
    try:
        return (paths.altium_scripts() / MARKER).read_text(encoding="utf-8").strip()
    except OSError:
        return None


def scripts_current() -> bool:
    return paths.script_project().is_file() and deployed_build() == build_id()


def ensure_folders() -> None:
    for p in paths.data_dirs().values():
        p.mkdir(parents=True, exist_ok=True)


def migrate_legacy(report: Callable[[str], None] = _log) -> None:
    """Copy the verified store and fab profiles from an older install once."""
    legacy = paths.legacy_home()
    for name, dest in (("verified", paths.verified()),
                       ("fab_profiles", paths.fab_profiles())):
        src = legacy / name
        if not src.is_dir() or (dest.is_dir() and any(dest.iterdir())):
            continue
        shutil.copytree(src, dest, dirs_exist_ok=True)
        report(f"copied {name} from {src} (the original stays)")


def deploy_scripts(report: Callable[[str], None] = _log) -> bool:
    """Copy the Altium script project to every folder Altium loads it from.

    The engine writes the Boardwright folder first, then every folder an
    Altium install already registers, so whichever copy Altium compiles
    is this build. Its console text is kept and shown only on failure.
    """
    from eda_agent import cli as engine_cli

    targets = engine_cli.get_install_targets()
    out = io.StringIO()
    with contextlib.redirect_stdout(out), contextlib.redirect_stderr(out):
        code = engine.run_engine_cli(["install-scripts", "--force"])
    if code != 0:
        report("deploying the Altium scripts failed:\n" + out.getvalue())
        return False
    (paths.altium_scripts() / MARKER).write_text(build_id() + "\n", encoding="utf-8")
    for target in targets:
        report(f"Altium scripts deployed to {target}")
    return True


LAUNCHER = "Start Boardwright in Altium.cmd"


def launcher() -> Path:
    return paths.home() / LAUNCHER


def launcher_text() -> str:
    python = Path(sys.executable).resolve()
    return ("@echo off\r\n"
            "chcp 65001 >nul\r\n"
            f"rem Written by Boardwright {__version__}: starts the Boardwright bridge\r\n"
            "rem in the running Altium Designer. Rewritten when Boardwright updates.\r\n"
            f'"{python}" -I -m boardwright relaunch\r\n'
            "if errorlevel 1 (echo. & pause) else (timeout /t 5 >nul)\r\n")


def write_launcher() -> Optional[Path]:
    """Write the start-the-bridge launcher when it is missing or names an
    old runtime. Only an installed runtime has an interpreter worth naming."""
    if paths.install_root() is None:
        return None
    target, text = launcher(), launcher_text()
    try:
        current = target.read_bytes().decode("utf-8")
    except (OSError, UnicodeDecodeError):
        current = None
    if current != text:
        target.write_bytes(text.encode("utf-8"))
    return target


def ensure_ready(report: Callable[[str], None] = _log) -> dict:
    """Run every step that is needed; never raises.

    Returns what happened, for boardwright_info and the doctor.
    """
    state = {"folders": False, "scripts": "current", "error": None}
    try:
        ensure_folders()
        state["folders"] = True
        migrate_legacy(report)
        if not scripts_current():
            state["scripts"] = "deployed" if deploy_scripts(report) else "failed"
        write_launcher()
    except Exception as exc:  # a broken PC must not stop the server starting
        state["error"] = f"{type(exc).__name__}: {exc}"
        report(f"preparing this PC failed: {state['error']}")
    return state
